import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  const brandMarks = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES'
  ];

  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const gridW = 3 * tileW + 2 * gap;
  const gridH = 2 * tileH + 1 * gap;
  const startX = -gridW / 2;
  const startY = gridH / 2;

  // Create gradient texture: #1a1a22 → #121218 (vertical)
  const gradTex = new THREE.DataTexture(
    createVerticalGradient(1, 256, [0x1a, 0x1a, 0x22], [0x12, 0x12, 0x18]),
    1, 256,
    THREE.RGBAFormat,
    THREE.UnsignedByteType
  );
  gradTex.magFilter = THREE.LinearFilter;
  gradTex.minFilter = THREE.LinearFilter;
  gradTex.needsUpdate = true;
  disposables.push(gradTex);

  // Kicker: "AS FEATURED IN"
  const kickerGrp = new THREE.Group();
  kickerGrp.position.y = startY + 0.3;
  const kickerMesh = ctx.fontAtlas?.createText?.({
    text: 'AS FEATURED IN',
    size: 0.09 * 1.33,
    weight: 700,
    family: 'JetBrains Mono',
    color: '#e8ecf2',
    opacity: 0.78,
    letterSpacing: 0.12
  }) || new THREE.Group();
  kickerGrp.add(kickerMesh);
  group.add(kickerGrp);

  // 6 tiles in 3×2 grid
  let idx = 0;
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const tileGrp = new THREE.Group();
      const tx = startX + col * (tileW + gap) + tileW / 2;
      const ty = startY - row * (tileH + gap) - tileH / 2;

      tileGrp.position.set(tx, ty, 0);

      // Tile plane geometry
      const geo = new THREE.PlaneGeometry(tileW, tileH);
      const mat = new THREE.MeshStandardNodeMaterial({
        map: gradTex,
        metalness: 0.5,
        roughness: 0.55,
        clearcoat: 0.2,
        clearcoatRoughness: 0.1,
        side: THREE.FrontSide
      });
      disposables.push(geo, mat);

      const tileMesh = new THREE.Mesh(geo, mat);
      tileMesh.castShadow = true;
      tileMesh.receiveShadow = true;
      tileGrp.add(tileMesh);

      // Brand wordmark text on tile
      const brandMesh = ctx.fontAtlas?.createText?.({
        text: brandMarks[idx],
        size: 0.13 * 1.33,
        weight: 700,
        family: 'JetBrains Mono',
        color: '#e8ecf2',
        opacity: 0.78,
        letterSpacing: 0.08
      }) || new THREE.Group();
      brandMesh.position.z = 0.015;
      tileGrp.add(brandMesh);

      // Mount animation: stagger-cards (fade-up + y offset)
      const initialTy = ty;
      tileGrp.position.y = initialTy + 0.2;

      const staggerDelay = idx * 0.08;
      const tl = gsap.timeline();

      tl.to(
        tileGrp.position,
        {
          y: initialTy,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        },
        staggerDelay
      );

      if (tileMesh.material.opacity !== undefined) {
        tl.to(
          tileMesh.material,
          {
            opacity: 1,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          },
          staggerDelay
        );
      }

      if (brandMesh.material?.opacity !== undefined) {
        tl.to(
          brandMesh.material,
          {
            opacity: 0.78,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          },
          staggerDelay
        );
      }

      timelines.push(tl);

      // Hover: wordmark opacity 0.78→1.0, tile z 0→0.05
      tileGrp.userData.handlers = {
        onPointerEnter: () => {
          gsap.to(brandMesh, { opacity: 1.0, duration: 0.16, overwrite: 'auto' });
          gsap.to(tileGrp.position, { z: 0.05, duration: 0.16, overwrite: 'auto' });
        },
        onPointerLeave: () => {
          gsap.to(brandMesh, { opacity: 0.78, duration: 0.16, overwrite: 'auto' });
          gsap.to(tileGrp.position, { z: 0, duration: 0.16, overwrite: 'auto' });
        }
      };

      group.add(tileGrp);
      idx++;
    }
  }

  // Apply scenePosition
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
    if (config.scenePosition.rotationXYZ) {
      group.rotation.order = 'XYZ';
      group.rotation.set(
        config.scenePosition.rotationXYZ[0],
        config.scenePosition.rotationXYZ[1],
        config.scenePosition.rotationXYZ[2]
      );
    }
    if (config.scenePosition.scaleXYZ) {
      group.scale.set(
        config.scenePosition.scaleXYZ[0],
        config.scenePosition.scaleXYZ[1],
        config.scenePosition.scaleXYZ[2]
      );
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    disposables.forEach(d => d.dispose?.());
    timelines.forEach(tl => tl.kill());
  };

  return group;
}

function createVerticalGradient(width, height, colorTop, colorBot) {
  const data = new Uint8Array(width * height * 4);
  for (let y = 0; y < height; y++) {
    const t = y / (height - 1);
    const r = Math.round(colorTop[0] + (colorBot[0] - colorTop[0]) * t);
    const g = Math.round(colorTop[1] + (colorBot[1] - colorTop[1]) * t);
    const b = Math.round(colorTop[2] + (colorBot[2] - colorTop[2]) * t);
    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      data[idx] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = 255;
    }
  }
  return data;
}
